mapper.sql:
FROM auth_principal_role_assignment assignment
JOIN auth_role_capability role_capability
  ON role_capability.role_id = assignment.role_id
JOIN auth_capability capability
  ON capability.capability_id = role_capability.capability_id
 AND capability.capability_code = #{capability}
JOIN auth_data_scope scope ON scope.scope_id = assignment.data_scope_id
WHERE assignment.principal_id = #{principalId}
  AND assignment.valid_from <= #{at}
  AND (assignment.valid_to IS NULL OR assignment.valid_to > #{at})
  AND scope.valid_from <= #{at}
  AND (scope.valid_to IS NULL OR scope.valid_to > #{at})

mapper.select:
SELECT CASE WHEN EXISTS (
    SELECT 1

      AND scope.scope_type = 'LEGAL_ENTITY'
      AND scope.legal_entity_id = #{legalEntityId}
) THEN TRUE ELSE FALSE END

SELECT CASE WHEN EXISTS (
    SELECT 1

      AND (
        scope.scope_type = 'LEGAL_ENTITY'
        AND scope.legal_entity_id = (
            SELECT legal_entity_id FROM organization_identity
            WHERE organization_id = #{organizationId}
        )
        OR scope.scope_type = 'ORGANIZATION'
        AND (
            scope.organization_id = #{organizationId}
            OR scope.include_descendants = TRUE AND EXISTS (
                SELECT 1 FROM organization_current_closure closure
                WHERE closure.ancestor_organization_id = scope.organization_id
                  AND closure.descendant_organization_id = #{organizationId}
            )
        )
      )
) THEN TRUE ELSE FALSE END

SELECT CASE WHEN EXISTS (
    SELECT 1

      AND (
        scope.scope_type = 'LEGAL_ENTITY'
        AND scope.legal_entity_id = (
            SELECT legal_entity_id FROM employee WHERE employee_id = #{employeeId}
        )
        OR scope.scope_type = 'SELF'
        AND EXISTS (
            SELECT 1 FROM auth_principal principal
            WHERE principal.principal_id = #{principalId}
              AND principal.employee_id = #{employeeId}
        )
        OR scope.scope_type = 'ORGANIZATION'
        AND EXISTS (
            SELECT 1
            FROM employment_assignment employment
            WHERE employment.employee_id = #{employeeId}
              AND employment.version_valid_to IS NULL
              AND employment.record_status = 'ACTIVE'
              AND DATE(employment.effective_from) <= #{asOf}
              AND (employment.effective_to IS NULL
                   OR DATE(employment.effective_to) > #{asOf})
              AND (
                employment.organization_id = scope.organization_id
                OR scope.include_descendants = TRUE AND EXISTS (
                    SELECT 1 FROM organization_current_closure closure
                    WHERE closure.ancestor_organization_id = scope.organization_id
                      AND closure.descendant_organization_id =
                          employment.organization_id
                )
              )
        )
      )
) THEN TRUE ELSE FALSE END

SELECT CASE WHEN EXISTS (
    SELECT 1 FROM legal_entity WHERE legal_entity_id = #{legalEntityId}
) THEN TRUE ELSE FALSE END

SELECT actor_id, action_code, idempotency_key, request_digest, resource_id, result_json
FROM people_idempotency_record
WHERE actor_id = #{actorId}
  AND action_code = #{actionCode}
  AND idempotency_key = #{idempotencyKey}

mapper.insert:
INSERT INTO people_idempotency_record (
    idempotency_record_id, actor_id, action_code, idempotency_key,
    request_digest, resource_id, result_json, created_at
) VALUES (
    #{id}, #{actorId}, #{actionCode}, #{idempotencyKey},
    #{requestDigest}, #{resourceId}, #{resultJson}, #{at}
)

INSERT INTO people_import_file (
    file_id, batch_id, original_file_name, media_type, size_bytes,
    sha256, content, uploaded_by, uploaded_at
) VALUES (
    #{fileId}, #{batchId}, #{originalFileName}, #{mediaType}, #{sizeBytes},
    #{storedFileSha256}, #{content}, #{uploadedBy}, #{uploadedAt}
)

mapper.update:
UPDATE people_import_batch
SET file_sha256 = #{fileSha256},
    status = 'DRAFT',
    row_version = row_version + 1,
    updated_by = #{actorId},
    updated_at = #{at}
WHERE batch_id = #{batchId}
  AND row_version = #{expectedVersion}
  AND file_sha256 IS NULL

