INSERT INTO people_import_diff (
    diff_id, batch_id, `row_number`, entity_type, category,
    matched_resource_id, source_values_json, current_values_json,
    proposed_values_json
) VALUES (
    #{diffId}, #{batchId}, #{rowNumber}, #{entityType}, #{category},
    #{matchedResourceId}, #{sourceValuesJson}, #{currentValuesJson},
    #{proposedValuesJson}
)

INSERT INTO people_import_issue (
    issue_id, batch_id, `row_number`, field_name, issue_code,
    message, severity, candidate_employee_ids_json
) VALUES (
    #{issueId}, #{batchId}, #{rowNumber}, #{fieldName}, #{issueCode},
    #{message}, #{severity}, #{candidateEmployeeIdsJson}
)

mapper.select:
SELECT COUNT(*) FROM people_import_diff
WHERE batch_id = #{batchId}
  AND (#{category} IS NULL OR category = #{category})

SELECT COUNT(*) FROM people_import_issue
WHERE batch_id = #{batchId}
  AND (#{severity} IS NULL OR severity = #{severity})


WHERE legal_entity_id = #{legalEntityId}
  AND template_type = #{templateType}
  AND template_version = #{templateVersion}
  AND file_sha256 = #{fileSha256}

