INSERT INTO people_import_rollback (
    rollback_id, batch_id, source_publication_id, idempotency_key,
    reason, restored_snapshot_digest, created_version_ids_json,
    rolled_back_by, rolled_back_at
) VALUES (
    #{row.rollbackId}, #{row.batchId}, #{row.sourcePublicationId},
    #{idempotencyKey}, #{reason}, #{row.restoredSnapshotDigest},
    #{row.createdVersionIdsJson}, #{row.rolledBackBy}, #{row.rolledBackAt}
)

mapper.select:

WHERE version.organization_id = #{organizationId}
  AND DATE(version.effective_from) <= #{asOf}
  AND (version.effective_to IS NULL OR DATE(version.effective_to) > #{asOf})
ORDER BY version.effective_from DESC
LIMIT 1


JOIN organization_current_projection projection
  ON projection.organization_id = version.organization_id
 AND projection.current_version_id = version.organization_version_id
WHERE identity.legal_entity_id = #{legalEntityId}
  AND version.code = #{code}


WHERE version.organization_id = #{organizationId}
ORDER BY version.effective_from DESC, version.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT CASE WHEN #{parentOrganizationId} IS NOT NULL AND (
    #{parentOrganizationId} = #{organizationId}
    OR EXISTS (
        SELECT 1 FROM organization_current_closure closure
        WHERE closure.ancestor_organization_id = #{organizationId}
          AND closure.descendant_organization_id = #{parentOrganizationId}
    )
) THEN TRUE ELSE FALSE END

mapper.insert:
INSERT INTO organization_identity (
    organization_id, legal_entity_id, identity_status, created_at
) VALUES (#{organizationId}, #{legalEntityId}, #{status}, #{at})

mapper.update:
UPDATE organization_identity
SET identity_status = #{status}
WHERE organization_id = #{organizationId}

UPDATE organization_version
SET effective_to = COALESCE(effective_to, #{effectiveTo})
WHERE organization_version_id = (
    SELECT projection.current_version_id
    FROM organization_current_projection projection
    WHERE projection.organization_id = #{organizationId}
)
  AND row_version = #{expectedVersion}

mapper.insert:
INSERT INTO organization_current_projection (
    organization_id, current_version_id, projection_batch_id, projected_at
) VALUES (
    #{organizationId}, #{versionId}, #{projectionBatchId}, #{at}
)
ON DUPLICATE KEY UPDATE
    current_version_id = VALUES(current_version_id),
    projection_batch_id = VALUES(projection_batch_id),
    projected_at = VALUES(projected_at)

mapper.select:

WHERE version.employee_id = #{employeeId}
  AND version.effective_from <= #{asOf}
  AND (version.effective_to IS NULL OR version.effective_to > #{asOf})
ORDER BY version.effective_from DESC
LIMIT 1


JOIN employee_current_projection projection
  ON projection.employee_id = version.employee_id
 AND projection.current_version_id = version.employee_version_id
WHERE employee.legal_entity_id = #{legalEntityId}
  AND version.employee_number = #{employeeNumber}


JOIN employee_current_projection projection
  ON projection.employee_id = version.employee_id
 AND projection.current_version_id = version.employee_version_id
WHERE employee.legal_entity_id = #{legalEntityId}
  AND version.external_employee_id = #{externalEmployeeId}
ORDER BY version.employee_id


WHERE version.employee_id = #{employeeId}
ORDER BY version.effective_from DESC, version.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT CASE WHEN EXISTS (
    SELECT 1 FROM employee
    WHERE legal_entity_id = #{legalEntityId}
      AND employee_number = #{employeeNumber}
      AND (#{excludeEmployeeId} IS NULL OR employee_id <> #{excludeEmployeeId})
) THEN TRUE ELSE FALSE END

mapper.insert:
INSERT INTO employee (
    employee_id, legal_entity_id, employee_number, display_name,
    employment_status, onboard_date, row_version, created_at, updated_at
) VALUES (
    #{employeeId}, #{legalEntityId}, #{employeeNumber}, #{displayName},
    #{status}, #{onboardDate}, 0, #{at}, #{at}
)

mapper.update:
UPDATE employee
SET employee_number = #{employeeNumber},
    display_name = #{displayName},
    employment_status = #{status},
    row_version = row_version + 1,
    updated_at = #{at}
WHERE employee_id = #{employeeId}
  AND row_version = #{expectedVersion}

UPDATE employee_version
SET effective_to = COALESCE(effective_to, #{effectiveTo})
WHERE employee_version_id = (
    SELECT projection.current_version_id
    FROM employee_current_projection projection
    WHERE projection.employee_id = #{employeeId}
)
  AND EXISTS (
    SELECT 1
    FROM employee identity
    WHERE identity.employee_id = #{employeeId}
      AND identity.row_version = #{expectedVersion}
  )

mapper.select:

  AND employee_id = #{employeeId}
  AND (#{asOf} IS NULL
       OR DATE(effective_from) <= #{asOf}
          AND (effective_to IS NULL OR DATE(effective_to) > #{asOf}))
ORDER BY effective_from DESC, assignment_id
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE employee
SET row_version = row_version + 1,
    updated_at = #{at}
WHERE employee_id = #{employeeId}
  AND row_version = #{expectedVersion}

UPDATE employment_assignment
SET version_valid_to = CURRENT_TIMESTAMP
WHERE employment_period_id = #{employmentPeriodId}
  AND version_valid_to IS NULL
  AND row_version = #{expectedVersion}

